<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/Matching/GroupedMatchReviewService.php';
function runGroupedCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,array $users):void
{
 $actor=$users['admin'];$svc=new GroupedMatchReviewService($db);$bulk=new BulkExactMatchService($db,BulkExactMatchService::SCORE);
 $choose=static function(array $queue,string $kind):array{foreach($queue['groups'] as $g)if($g['kind']===$kind)return $g;throw new RuntimeException('fixture group missing');};
 $repeat=static function(array $over=[])use($q,$pair):array{$a=$pair($over);foreach([1,2] as $_){$b=$pair($over);$q('UPDATE identity_match_candidates SET stripe_customer_id=? WHERE stripe_customer_id=?',[$a['cid'],$b['cid']]);$q('DELETE FROM stripe_customers WHERE id=?',[$b['cid']]);}return $a;};
 $reset();$a=$repeat();$before=$hash();$queue=$svc->queue($actor);$g=$queue['groups'][0];
 bulkCheck($queue['summary']['total_groups']===1&&count($g['candidate_ids'])===6&&count($g['waiver_records'])===3,'regular queue consolidates three adult waivers and six comparisons into one group');
 bulkCheck($before===$hash(),'grouped queue and projection are read-only');
 foreach([1,2,3] as $n)$q('INSERT INTO stripe_transactions(stripe_charge_id,customer_id,amount_minor,currency,status) VALUES (?,?,?,?,?)',['ch_GroupFixture'.$n,$a['cid'],100,'usd','succeeded']);
 bulkCheck($svc->queue($actor)['groups'][0]['transaction_count']===3,'transaction count stays at customer grain rather than multiplying by six candidates');$q('DELETE FROM stripe_transactions');
 $p=$svc->preview($actor,$g['id']);bulkCheck($p['people_to_create']===1&&$p['members_to_create']===1&&count($p['selection'])===6,'same-person preview has precise one-person one-member six-candidate scope');$op=bin2hex(random_bytes(16));$svc->confirm($actor,$op,$p['digest'],$g['id'],'same',$p['selection']);$before=$hash();$svc->confirm($actor,$op,$p['digest'],$g['id'],'same',$p['selection']);
 bulkCheck($before===$hash()&&(int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===1,'grouped same-person replay is idempotent');bulkCheck($svc->queue($actor)['summary']['groups_needing_decision']===0,'verified repeated self-waivers no longer count as open workload');
 $reset();$a=$pair();$pair();$queue=$svc->queue($actor);bulkCheck(count($queue['groups'])===1&&count($queue['groups'][0]['customer_records'])===2,'compatible duplicate financial accounts consolidate without deleting them');
 $reset();$a=$repeat(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$queue=$svc->queue($actor);bulkCheck(count($queue['groups'])===2,'parent and child remain two distinct identity groups');$g=$choose($queue,'student');$p=$svc->preview($actor,$g['id'],'relationship');
 bulkCheck($p['blockers']===[]&&$p['people_to_create']===2&&$p['members_to_create']===1&&count($p['selection'])===3&&count($p['signer_selection'])===3,'parent preview creates two people one student member and reviews all six comparisons');
 $before=$hash();$db->arm(2);bulkThrows(fn()=>$svc->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$g['id'],'relationship'),'SYNTHETIC_PARTIAL_FAILURE','partial grouped relationship failure is surfaced');$db->arm(0);bulkCheck($before===$hash(),'failed parent group rolls back people links members relationships candidates and all audits');
 $op=bin2hex(random_bytes(16));$svc->confirm($actor,$op,$p['digest'],$g['id'],'relationship');
 bulkCheck((int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===2&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===1,'three child waivers produce exactly one payer one student one member');
 bulkCheck((int)$q("SELECT COUNT(*) FROM person_relationships WHERE relationship_type='payer'")->fetchColumn()===1&&(int)$q('SELECT COUNT(*) FROM cognito_waivers')->fetchColumn()===3,'one payer edge and all three source waivers retained');
 bulkCheck((int)$q("SELECT COUNT(*) FROM members m JOIN cognito_waivers w ON w.signer_person_id=m.person_id")->fetchColumn()===0,'signing parent is never made a member');
 bulkCheck((int)$q("SELECT COUNT(*) FROM audit_log WHERE action IN ('match_review_confirm_same','match_review_confirm_relationship')")->fetchColumn()===6,'every underlying candidate has its individual decision audit');
 $before=$hash();$svc->confirm($actor,$op,$p['digest'],$g['id'],'relationship');bulkCheck($before===$hash(),'parent group receipt prevents duplicate people relationships and audit entries');
 bulkCheck($svc->queue($actor)['summary']['groups_needing_decision']===0,'relationship decisions resolve payer and student workload without same-person merging');
 $reset();$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$pair(['student'=>'Luke Smith','relationship'=>'Father','dob'=>'2013-01-01']);$queue=$svc->queue($actor);bulkCheck(count(array_filter($queue['groups'],fn($g)=>$g['kind']==='student'))===2,'different children sharing a parent and contact email stay separate');
 $reset();$pair(['dob'=>'1980-01-01']);$pair(['dob'=>'1990-01-01']);$queue=$svc->queue($actor);bulkCheck(count($queue['groups'])===2&&$queue['summary']['unresolved_conflicts']===2,'contradictory self birth dates remain separate conflict groups');
 foreach(['reject','later'] as $action){$reset();$a=$pair();(new MatchReviewService($db))->decide($a['ids']['signer'],$action,$actor,[]);$queue=$svc->queue($actor,'','all');$p=$svc->preview($actor,$queue['groups'][0]['id']);bulkCheck($p['selection']===[],'manual '.$action.' prevents grouped confirmation');}
 $reset();$a=$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$ppl=(new People($db))->create('Emma','Smith');$idn=new IdentityAssociations($db);$idn->decide('cognito','waiver',$a['locator'],'student',(int)$ppl['id'],'confirmed',$actor);$g=$choose($svc->queue($actor),'student');$p=$svc->preview($actor,$g['id'],'relationship');bulkCheck($p['people_to_reuse']===1&&$p['people_to_create']===1&&$p['blockers']===[],'accepted existing student BMA identity is reused');
 $b=(new People($db))->create('John','Smith');$c=(new People($db))->create('John','Smith');$idn->decide('stripe','customer',$a['external'],'customer',(int)$b['id'],'confirmed',$actor);$idn->decide('cognito','waiver',$a['locator'],'signer',(int)$c['id'],'confirmed',$actor);$g=$choose($svc->queue($actor),'student');bulkCheck($svc->preview($actor,$g['id'],'relationship')['blockers']!==[],'competing accepted payer/signer BMA IDs block grouped relationship changes');
 $reset();$a=$pair(['format'=>'legacy','name_role'=>'unresolved']);bulkCheck($choose($svc->queue($actor),'unresolved')['eligible_ids']===[],'legacy name ambiguity never becomes a student identity automatically');
 $reset();$a=$pair();$g=$svc->queue($actor)['groups'][0];$p=$svc->preview($actor,$g['id']);(new MatchReviewService($db))->decide($a['ids']['signer'],'later',$actor,[]);bulkThrows(fn()=>$svc->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$g['id'],'same',$p['selection']),'BULK_PREVIEW_STALE','concurrent manual hold invalidates scoped confirmation');
 $reset();$pair();$pair(['payer'=>'Jane Smith','signer'=>'Jane Smith','student'=>'Jane Smith']);bulkCheck($svc->queue($actor)['summary']['total_groups']===2,'shared household email with distinct names never collapses people');
 $reset();$a=$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$b=$pair(['student'=>'Luke Smith','relationship'=>'Father','dob'=>'2013-01-01']);
 foreach(['Emma Smith','Luke Smith'] as $name){$groups=$svc->queue($actor)['groups'];$child=array_values(array_filter($groups,fn($g)=>$g['name']===$name))[0];$p=$svc->preview($actor,$child['id'],'relationship');bulkCheck($p['blockers']===[],'sibling relationship preview remains safe for '.$name);$svc->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$child['id'],'relationship');}
 bulkCheck((int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===3&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===2&&(int)$q("SELECT COUNT(*) FROM person_relationships WHERE relationship_type='payer'")->fetchColumn()===2,'successive sibling groups reuse one parent and create two separate student members');
 $reset();$a=$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$q('UPDATE identity_match_candidates SET match_score=0.50 WHERE id=?',[$a['ids']['source_name_unresolved']]);$child=$choose($svc->queue($actor),'student');bulkCheck($svc->preview($actor,$child['id'],'relationship')['blockers']!==[],'exactly 50 percent is not eligible for grouped relationship confirmation');
 $reset();$a=$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$child=$choose($svc->queue($actor),'student');$p=$svc->preview($actor,$child['id'],'relationship');$other=new PDO('mysql:host='.getenv('DB_HOST').';port='.getenv('DB_PORT').';dbname='.$q('SELECT DATABASE()')->fetchColumn(),getenv('DB_USERNAME'),getenv('DB_PASSWORD'));$lock='bma_bulk_exact_'.substr(hash('sha256',(string)$q('SELECT DATABASE()')->fetchColumn()),0,40);$other->prepare('SELECT GET_LOCK(?,0)')->execute([$lock]);bulkThrows(fn()=>$svc->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$child['id'],'relationship'),'BULK_BUSY','concurrent connection cannot enter grouped parent decision');$other->prepare('SELECT RELEASE_LOCK(?)')->execute([$lock]);$other=null;
 $reset();$a=$pair();$b=$pair(['payer'=>'Jane Smith','signer'=>'Jane Smith','student'=>'Jane Smith','payer_email'=>'jane@example.invalid','waiver_email'=>'jane@example.invalid']);$all=$svc->queue($actor);$filtered=$svc->queue($actor,'Jane');bulkCheck(count($filtered['groups'])===1&&$filtered['groups'][0]['name']==='Jane Smith'&&$filtered['summary']['total_groups']===2,'search filters whole identity groups while workload remains dataset-wide');
 $columns=$q("SHOW COLUMNS FROM stripe_customers LIKE 'phone%'")->fetchAll();bulkCheck($columns===[],'Stripe source has no person-owned phone; phone matching is explicitly unavailable');
}
function runGroupedHttpCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,callable $http,string $cookie,array $users):void
{
 $reset();$pair();$before=$hash();[$code,$html]=$http('/admin/matches.php',$cookie);bulkCheck($code===200&&substr_count($html,'class="review-card identity-group"')===1&&str_contains($html,'Groups needing decisions')&&$before===$hash(),'authenticated regular Matches GET shows one consolidated card and writes nothing');
 preg_match('/group-match.php\?group=([a-f0-9]+)&amp;action=same/',$html,$m);$url='/admin/group-match.php?group='.$m[1].'&action=same';[$code,$html]=$http($url,$cookie);bulkCheck($code===200&&str_contains($html,'Confirm 2 reviewed candidates')&&$before===$hash(),'group GET preview is precise and read-only');preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$csrf);preg_match('/name="operation_id" value="([a-f0-9]+)"/',$html,$op);
 foreach([[],['csrf'=>'bad']] as $bad){[$code]=$http($url,$cookie,$bad+['operation_id'=>$op[1],'acknowledge'=>'1','confirm_count'=>'2']);bulkCheck($code===403&&$before===$hash(),'group confirmation rejects missing/invalid CSRF without writes');}
 [$code]=$http($url,$cookie,['csrf'=>$csrf[1],'operation_id'=>$op[1],'acknowledge'=>'1','confirm_count'=>'3']);bulkCheck($code===409&&$before===$hash(),'group confirmation rejects a tampered count');
 [$code,$html]=$http($url,$cookie);preg_match('/name="operation_id" value="([a-f0-9]+)"/',$html,$op);$post=['csrf'=>$csrf[1],'operation_id'=>$op[1],'acknowledge'=>'1','confirm_count'=>'2'];[$code]=$http($url,$cookie,$post);bulkCheck($code===303&&(int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===1,'explicit session-authenticated group confirmation succeeds locally');$before=$hash();[$code]=$http($url,$cookie,$post);bulkCheck($code===303&&$before===$hash(),'repeated grouped HTTP confirmation replays without writes');
 [$code,$raw]=$http('/admin/matches.php?view=raw&status=all',$cookie);bulkCheck($code===200&&str_contains($raw,'candidate_id'),'raw troubleshooting workflow remains available');
 [$code]=$http($url);bulkCheck($code===303,'unauthenticated grouped endpoint redirects to application login');
 $q("UPDATE app_users SET role='viewer' WHERE id=?",[$users['admin']]);[$code]=$http($url,$cookie);bulkCheck($code===403,'canonical non-admin role cannot access grouped decisions');$q("UPDATE app_users SET role='admin' WHERE id=?",[$users['admin']]);
 $reset();$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$pair(['student'=>'Emma Smith','relationship'=>'Father','dob'=>'2015-01-01']);$pair(['payer'=>'Zoë <img src=x onerror=window.fixtureXss=1>','signer'=>'Zoë <img src=x onerror=window.fixtureXss=1>','student'=>'Zoë <img src=x onerror=window.fixtureXss=1>','payer_email'=>'zoe@example.invalid','waiver_email'=>'zoe@example.invalid']);
 [$code,$html]=$http('/admin/matches.php',$cookie);bulkCheck($code===200&&str_contains($html,'&lt;img')&&!str_contains($html,'<img src=x'),'grouped source names are escaped');
 $out=getenv('BMA_REVIEW_RENDER_DIR');if($out&&is_dir($out))file_put_contents($out.'/groups.html',$html);
 preg_match('/group-match.php\?group=([a-f0-9]+)&amp;action=relationship/',$html,$child);$url='/admin/group-match.php?group='.$child[1].'&action=relationship';$before=$hash();[$code,$html]=$http($url,$cookie);bulkCheck($code===200&&str_contains($html,'Confirm 4 reviewed candidates')&&$before===$hash(),'parent relationship HTTP preview lists all child and signer candidates without writes');if($out&&is_dir($out))file_put_contents($out.'/group-preview.html',$html);
 preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$csrf);preg_match('/name="operation_id" value="([a-f0-9]+)"/',$html,$op);$post=['csrf'=>$csrf[1],'operation_id'=>$op[1],'acknowledge'=>'1','confirm_count'=>'4'];[$code]=$http($url,$cookie,$post);bulkCheck($code===303&&(int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===2&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===1,'explicit grouped parent HTTP decision creates separate payer and child only');$before=$hash();[$code]=$http($url,$cookie,$post);bulkCheck($code===303&&$before===$hash(),'parent HTTP replay creates no additional associations');
 [$code,$html]=$http('/admin/matches.php?q=NoSuchFixturePerson',$cookie);bulkCheck($code===200&&str_contains($html,'No identity groups to review'),'grouped empty state contains no phantom cards');if($out&&is_dir($out))file_put_contents($out.'/groups-empty.html',$html);
 $dashboard=(int)$q("SELECT id FROM dashboards WHERE dashboard_key='matches'")->fetchColumn();$q("INSERT INTO user_dashboard_overrides(user_id,dashboard_id,permission) VALUES (?,?,'DENY')",[$users['admin'],$dashboard]);[$code]=$http($url,$cookie);bulkCheck($code===403,'Matches DENY also protects grouped decision endpoint');$q('DELETE FROM user_dashboard_overrides WHERE user_id=? AND dashboard_id=?',[$users['admin'],$dashboard]);
}
